`timescale 1ns/1ps
module tb_stream_primitives;
 logic[511:0]x,gamma,sm,rm,cs,ro,state,gate,next,table,gy,patch,scale,bias,adaln;logic[159:0]indices;logic[63:0]topv;logic[19:0]topi;logic[127:0]cand,refv;logic[3:0]accepted;integer i;integer sum;
 fx_rmsnorm32 u0(.x,.gamma,.epsilon_q16_16(32'd1),.y(rm));fx_softmax32 u1(.x,.y(sm));fx_rope32 u2(.x,.cos_sin(cs),.y(ro));fx_state_update32 u3(.x,.state,.gate,.next_state(next));fx_topk32 #(.K(4))u4(.x,.values(topv),.indices(topi));fx_mtp_verify8 u5(.candidate(cand),.reference(refv),.accepted);fx_sparse_gather32 u6(.table,.indices,.y(gy));fx_patchify3d u7(.x,.y(patch));fx_adaln32 u8(.x,.scale,.bias,.y(adaln));
 initial begin x='0;gamma='0;cs='0;state='0;gate='0;table='0;indices='0;scale='0;bias='0;for(i=0;i<32;i=i+1)begin x[i*16 +:16]=i-16;gamma[i*16 +:16]=256;cs[i*16 +:16]=(i%2==0)?256:0;gate[i*16 +:16]=16384;table[i*16 +:16]=i*10;indices[i*5 +:5]=31-i;scale[i*16 +:16]=256;bias[i*16 +:16]=4;end cand={16'd8,16'd7,16'd6,16'd5,16'd4,16'd3,16'd2,16'd1};refv={16'd9,16'd7,16'd6,16'd5,16'd4,16'd3,16'd2,16'd1};#2;if(ro!==x)$fatal(1,"rope identity-angle mismatch");if(accepted!=7)$fatal(1,"mtp expected 7 got %0d",accepted);if($signed(gy[0+:16])!=310)$fatal(1,"gather");if($signed(adaln[0+:16])!=$signed(x[0+:16])+4)$fatal(1,"adaln");sum=0;for(i=0;i<32;i=i+1)sum=sum+sm[i*16 +:16];if(sum<65000||sum>65600)$fatal(1,"softmax sum %0d",sum);$display("PASS tb_stream_primitives");$finish;end
